/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
const hasRepair = false;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 0;
const numSymbols = 144;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"newline" => 77,
        .@"kw_lexer" => 79,
        .@"kw_parser" => 80,
        .@"kw_state" => 81,
        .@"kw_after" => 82,
        .@"kw_tokens" => 83,
        .@"kw_code" => 84,
        .@"ident" => 86,
        .@"cont" => 87,
        .@"integer" => 88,
        .@"pattern" => 90,
        .@"arrow" => 91,
        .@"amp" => 92,
        .@"compare" => 95,
        .@"lbrace" => 98,
        .@"rbrace" => 99,
        .@"quoted" => 100,
        .@"incdec" => 101,
        .@"kw_lang" => 102,
        .@"string" => 103,
        .@"kw_conflicts" => 104,
        .@"kw_as" => 105,
        .@"kw_op" => 106,
        .@"kw_errors" => 109,
        .@"kw_display" => 110,
        .@"kw_infix" => 111,
        .@"kw_schema" => 112,
        .@"kw_tags" => 113,
        .@"kw_trivia" => 114,
        .@"kw_repair" => 115,
        .@"rule_text" => 116,
        .@"comment" => 117,
        .@"kw_over" => 119,
        .@"token" => 120,
        .@"kw_via" => 121,
        .@"label" => 122,
        .@"kw_left" => 124,
        .@"kw_right" => 125,
        .@"kw_none" => 126,
        .@"kw_wrapper" => 128,
        .@"union" => 131,
        .@"next_alt" => 132,
        .@"kw_x" => 136,
        .@"kw_list" => 137,
        .@"kw_nil" => 140,
        .@"word" => 141,
        .@"at" => 78,
        .@"eq" => 85,
        .@"comma" => 89,
        .@"bang" => 93,
        .@"lparen" => 96,
        .@"rparen" => 97,
        .@"lbracket" => 107,
        .@"rbracket" => 108,
        .@"colon" => 123,
        .@"pipe" => 127,
        .@"question" => 129,
        .@"langle" => 133,
        .@"rangle" => 134,
        .@"tilde" => 135,
        .@"star" => 138,
        .@"plus" => 139,
        .@"dots" => 130,
        else => 2, // error
    };
}

fn promote(_: *BaseParser, _: Token) u16 {
    unreachable; // no @as group
}

