        .@"repair" => if (role == .@"lines") 1 else null,
        .@"repair_line" => if (role == .@"names") 2 else null,
        .@"rule" => if (role == .@"alts") 2 else null,
        .@"group" => if (role == .@"bodies") 2 else null,
        .@"node" => if (role == .@"items") 2 else null,
        .@"list" => if (role == .@"items") 1 else null,
        .@"keep" => if (role == .@"items") 2 else null,
        else => null,
    };
}

/// The slot role at `slot` of nodes of `kind`.
fn roleAt(kind: Tag, slot: usize) ?Role {
    return switch (kind) {
        .@"section" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"state" => switch (slot) {
            1 => .@"keyword",
            else => null,
        },
        .@"after" => switch (slot) {
            1 => .@"keyword",
            else => null,
        },
        .@"assign" => switch (slot) {
            1 => .@"name",
            2 => .@"value",
            else => null,
        },
        .@"tokens" => switch (slot) {
            1 => .@"keyword",
            else => null,
        },
        .@"code" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"lex_rule" => switch (slot) {
            1 => .@"pattern",
            2 => .@"guards",
            3 => .@"token",
            else => null,
        },
        .@"guards" => switch (slot) {
            1 => .@"at",
            else => null,
        },
        .@"guard" => switch (slot) {
            1 => .@"neg",
            2 => .@"var",
            3 => .@"op",
            4 => .@"value",
            else => null,
        },
        .@"lex_action" => switch (slot) {
            1 => .@"word",
            2 => .@"arg",
            else => null,
        },
        .@"set_action" => switch (slot) {
            1 => .@"name",
            2 => .@"value",
            else => null,
        },
        .@"step_action" => switch (slot) {
            1 => .@"name",
            2 => .@"op",
            else => null,
        },
        .@"counted" => switch (slot) {
            1 => .@"name",
            2 => .@"fn",
            3 => .@"char",
            else => null,
        },
        .@"lang" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"conflict" => switch (slot) {
            1 => .@"kind",
            2 => .@"rule",
            3 => .@"over",
            4 => .@"count",
            5 => .@"reason",
            else => null,
        },
        .@"as" => switch (slot) {
            1 => .@"token",
            2 => .@"via",
            else => null,
        },
        .@"as_entry" => switch (slot) {
            1 => .@"perm",
            2 => .@"group",
            3 => .@"via",
            else => null,
        },
        .@"op_map" => switch (slot) {
            1 => .@"lit",
            2 => .@"token",
            else => null,
        },
        .@"name_pair" => switch (slot) {
            1 => .@"key",
            2 => .@"name",
            else => null,
        },
        .@"infix" => switch (slot) {
            1 => .@"base",
            else => null,
        },
        .@"infix_op" => switch (slot) {
            1 => .@"op",
            2 => .@"assoc",
            else => null,
        },
        .@"kind_decl" => switch (slot) {
            1 => .@"kinds",
            2 => .@"roles",
            3 => .@"sides",
            4 => .@"wrapper",
            else => null,
        },
        .@"role" => switch (slot) {
            1 => .@"rest",
            2 => .@"name",
            3 => .@"type",
            4 => .@"opt",
            else => null,
        },
        .@"tagset" => switch (slot) {
            1 => .@"tag",
            else => null,
        },
        .@"repair_line" => switch (slot) {
            1 => .@"class",
            else => null,
        },
        .@"rule" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"start" => switch (slot) {
            1 => .@"id",
            else => null,
        },
        .@"name" => switch (slot) {
            1 => .@"id",
            else => null,
        },
        .@"alt" => switch (slot) {
            1 => .@"hint",
            2 => .@"elements",
            3 => .@"action",
            4 => .@"optout",
            else => null,
        },
        .@"ref" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"tok" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"lit" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"at_ref" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"list_req" => switch (slot) {
            1 => .@"keyword",
            2 => .@"inner",
            else => null,
        },
        .@"plain" => switch (slot) {
            1 => .@"item",
            else => null,
        },
        .@"opt_items_nosep" => switch (slot) {
            1 => .@"item",
            else => null,
        },
        .@"sep_items" => switch (slot) {
            1 => .@"item",
            2 => .@"sep",
            else => null,
        },
        .@"opt_items" => switch (slot) {
            1 => .@"item",
            2 => .@"sep",
            else => null,
        },
        .@"group" => switch (slot) {
            1 => .@"kind",
            else => null,
        },
        .@"quantified" => switch (slot) {
            1 => .@"element",
            2 => .@"quant",
            else => null,
        },
        .@"skip_q" => switch (slot) {
            1 => .@"element",
            2 => .@"quant",
            else => null,
        },
        .@"skip" => switch (slot) {
            1 => .@"element",
            else => null,
        },
        .@"exclude" => switch (slot) {
            1 => .@"char",
            else => null,
        },
        .@"label" => switch (slot) {
            1 => .@"name",
            2 => .@"element",
            else => null,
        },
        .@"pos" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        .@"spread" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        .@"symid" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        .@"tag" => switch (slot) {
            1 => .@"word",
            else => null,
        },
        .@"named" => switch (slot) {
            1 => .@"role",
            2 => .@"value",
            else => null,
        },
        .@"node" => switch (slot) {
            1 => .@"head",
            else => null,
        },
        .@"keep" => switch (slot) {
            1 => .@"n",
            else => null,
        },
        else => null,
    };
}

fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"grammar" => .{ .role = .@"entries", .slot = 1 },
        .@"state" => .{ .role = .@"vars", .slot = 2 },
        .@"after" => .{ .role = .@"vars", .slot = 2 },
        .@"tokens" => .{ .role = .@"names", .slot = 2 },
        .@"lex_rule" => .{ .role = .@"actions", .slot = 4 },
        .@"guards" => .{ .role = .@"conds", .slot = 2 },
        .@"manifest" => .{ .role = .@"entries", .slot = 1 },
        .@"as" => .{ .role = .@"groups", .slot = 3 },
        .@"op" => .{ .role = .@"maps", .slot = 1 },
        .@"errors" => .{ .role = .@"pairs", .slot = 1 },
        .@"display" => .{ .role = .@"pairs", .slot = 1 },
        .@"infix" => .{ .role = .@"levels", .slot = 2 },
        .@"level" => .{ .role = .@"ops", .slot = 1 },
        .@"schema" => .{ .role = .@"decls", .slot = 1 },
        .@"kinds" => .{ .role = .@"names", .slot = 1 },
        .@"sides" => .{ .role = .@"names", .slot = 1 },
        .@"roles" => .{ .role = .@"roles", .slot = 1 },
        .@"type" => .{ .role = .@"atoms", .slot = 1 },
        .@"tagset" => .{ .role = .@"values", .slot = 2 },
        .@"tags" => .{ .role = .@"names", .slot = 1 },
        .@"trivia" => .{ .role = .@"names", .slot = 1 },
        .@"repair" => .{ .role = .@"lines", .slot = 1 },
        .@"repair_line" => .{ .role = .@"names", .slot = 2 },
        .@"rule" => .{ .role = .@"alts", .slot = 2 },
        .@"group" => .{ .role = .@"bodies", .slot = 2 },
        .@"node" => .{ .role = .@"items", .slot = 2 },
        .@"list" => .{ .role = .@"items", .slot = 1 },
        .@"keep" => .{ .role = .@"items", .slot = 2 },
        else => null,
    };
}

// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole grammar with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseGrammar(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseGrammar();
    return .{ .parser = p, .sexp = sexp };
}
